#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

// 独立实现：排序后求最长的“严格 +1 连续”段（重复值跳过）。
static long long expected(const string& in) {
    istringstream iss(in);
    int n;
    iss >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) iss >> a[i];
    sort(a.begin(), a.end());
    long long best = 1, cur = 1;
    for (int i = 1; i < n; i++) {
        if (a[i] == a[i - 1]) continue;
        if (a[i] == a[i - 1] + 1) cur++;
        else cur = 1;
        if (cur > best) best = cur;
    }
    return best;
}
static bool check(const string& exe, const string& in, int id) {
    const string inF = "l4a09p2_in.txt", outF = "l4a09p2_out.txt";
    {
        ofstream o(inF);
        o << in;
    }
