    for (size_t i = 0; i < fixedCases.size(); i++) {
        ++total;
        if (check(exe, fixedCases[i], 1 + i)) ++passed;
    }
    srand(20250902);
    for (int t = 0; t < 6; t++) {
        int n = 1 + rand() % 8;
        string in = to_string(n) + "\n";
