            in += to_string(v) + (i + 1 == n ? "\n" : " ");
        }
        ++total;
        if (check(exe, in, 7 + t)) ++passed;
    }
    for (int t = 0; t < 3; t++) {
        int n = 1 + rand() % 1000;
        string in = to_string(n) + "\n";
        for (int i = 0; i < n; i++) {
            long long v = -1000000000LL + (long long)rand() * rand() % 2000000001LL;
            in += to_string(v) + (i + 1 == n ? "\n" : " ");
